import React, { useState } from 'react';
import './RecipeGenerator.css';

const RecipeGenerator = ({ onRecipeGenerated }) => {
  const [ingredients, setIngredients] = useState('');
  const [servings, setServings] = useState(2);
  const [isLoading, setIsLoading] = useState(false);
  const [lastRecipeData, setLastRecipeData] = useState(null); // <-- Add this state

  const backendURL = "http://127.0.0.1:8000"; // FastAPI base URL

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!ingredients.trim()) return;
    setIsLoading(true);

    try {
      // Step 1: Fetch suggested recipes based on ingredients
      const suggestResponse = await fetch(
        backendURL + '/ingredients/suggest_recipes', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ingredients, top_n: 10 })
        }
      );

      if (!suggestResponse.ok) throw new Error("Failed to fetch recipe suggestions");

      const suggestions = await suggestResponse.json();

      // Step 2: Fetch full details for each suggested recipe
      const fullRecipes = await Promise.all(
        suggestions.map(async (r) => {
          const fullResponse = await fetch(
            backendURL + '/ingredients/recipe_full/' + r.index, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ num_people: servings })
            }
          );
          const fullData = await fullResponse.json();
          return {
            id: r.index,
            name: fullData.dish_name,
            cuisine: fullData.cuisine,
            type: fullData.type,
            cookTime: fullData.time_to_prepare_minutes + ' mins',
            ingredients: fullData.ingredients.map((i) => ({ name: i })),
            instructions: fullData.instructions.split('\n'),
            matched: r.matched,
            missing: r.missing
          };
        })
      );

      const recipeData = {
        type: 'recipe-generation',
        query: ingredients,
        servings: servings,
        recipes: fullRecipes,
        totalFound: fullRecipes.length,
        // Collect all missing ingredients from all recipes
        missingIngredients: fullRecipes.flatMap(r => r.missing || [])
      };

      setIsLoading(false);
      setLastRecipeData(recipeData); // <-- Save for UI
      onRecipeGenerated(recipeData);
    } catch (err) {
      console.error("Error:", err);
      setIsLoading(false);
      alert("Error fetching recipes. Please make sure FastAPI is running.");
    }
  };

  return (
    <section className="recipe-generator">
      <div className="container">
        <div className="generator-header">
          <h1 className="page-title">Recipe Generator</h1>
          <p className="page-subtitle">
            Transform your ingredients into delicious recipes with AI
          </p>
        </div>

        <div className="generator-layout">
          <div className="input-section">
            <div className="main-form card">
              <div className="form-header">
                <span className="form-icon">🥘</span>
                <h2>Create Recipe</h2>
              </div>

              <form onSubmit={handleSubmit}>
                <div className="ingredient-input">
                  <label className="form-label">
                    <span className="label-icon">🧂</span>
                    Your Ingredients
                  </label>
                  <textarea
                    className="form-input form-textarea"
                    placeholder="Enter ingredients separated by commas&#10;e.g. chicken, rice, tomatoes, onions"
                    value={ingredients}
                    onChange={(e) => setIngredients(e.target.value)}
                    required
                  />
                </div>

                <div className="servings-input">
                  <label className="form-label">
                    <span className="label-icon">👥</span>
                    Servings
                  </label>
                  <div className="servings-control">
                    <button 
                      type="button" 
                      onClick={() => setServings(Math.max(1, servings - 1))}
                      className="servings-btn"
                    >−</button>
                    <input
                      type="number"
                      value={servings}
                      onChange={(e) => setServings(parseInt(e.target.value) || 1)}
                      className="servings-value"
                      min="1"
                      max="20"
                    />
                    <button 
                      type="button"
                      onClick={() => setServings(Math.min(20, servings + 1))}
                      className="servings-btn"
                    >+</button>
                  </div>
                </div>

                <button
                  type="submit"
                  className="generate-btn"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <>
                      <span className="spinner"></span>
                      Generating...
                    </>
                  ) : (
                    <>
                      <span className="btn-icon">✨</span>
                      Generate Recipes
                    </>
                  )}
                </button>
              </form>
            </div>

            <div className="features-grid">
              <div className="feature-card">
                <span className="feature-icon">🎯</span>
                <h3>Smart Matching</h3>
                <p>Find recipes that match your available ingredients</p>
              </div>
              <div className="feature-card">
                <span className="feature-icon">⚡</span>
                <h3>Instant Results</h3>
                <p>Get recipe suggestions in seconds</p>
              </div>
              <div className="feature-card">
                <span className="feature-icon">📊</span>
                <h3>Scale Servings</h3>
                <p>Automatically adjust quantities for any serving size</p>
              </div>
            </div>

            {/* Show missing ingredients if present */}
            {lastRecipeData && lastRecipeData.missingIngredients && lastRecipeData.missingIngredients.length > 0 && (
              <div className="missing-ingredients card" style={{ marginTop: 24 }}>
                <h3>❌ Missing Ingredients</h3>
                <ul>
                  {lastRecipeData.missingIngredients.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>

          <div className="info-section">
            <div className="stats-card card">
              <h3>🤖 AI-Powered Recipe Generation</h3>
              <div className="stats-grid">
                <div className="stat-item">
                  <span className="stat-value">10K+</span>
                  <span className="stat-label">Recipes</span>
                </div>
                <div className="stat-item">
                  <span className="stat-value">95%</span>
                  <span className="stat-label">Accuracy</span>
                </div>
                <div className="stat-item">
                  <span className="stat-value">50+</span>
                  <span className="stat-label">Cuisines</span>
                </div>
              </div>
            </div>

            <div className="tips-card card">
              <h3>💡 Pro Tips</h3>
              <ul className="tips-list">
                <li>Be specific with ingredient names</li>
                <li>Include quantities if known</li>
                <li>List ingredients in order of importance</li>
                <li>Add any dietary preferences</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default RecipeGenerator;
